class MembershipTable:
    def __init__(self, local_node_id: str):
        self.local_id = local_node_id
        self.members = {local_node_id: {'heartbeat': 0, 'status': 'alive'}}

    def heartbeat(self) -> None:
        self.members[self.local_id]['heartbeat'] += 1

    def update(self, node_id: str, heartbeat: int, status: str) -> None:
        if node_id not in self.members or heartbeat > self.members[node_id]['heartbeat']:
            self.members[node_id] = {'heartbeat': heartbeat, 'status': status}

