import unittest
from gossip.member import MembershipTable

class TestGossip(unittest.TestCase):
    def test_member_update(self):
        m = MembershipTable('n1')
        m.update('n2', 5, 'alive')
        self.assertEqual(m.members['n2']['status'], 'alive')

if __name__ == '__main__': unittest.main()
